def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_remaining = 0.2 * bins
    return np.where(remaining < 0, -np.inf, -np.exp(np.abs(remaining - optimal_remaining)))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    fill_ratio = 1.0 - (remaining / np.maximum(bins, 1e-8))
    target_ratio = 0.8
    penalty = (fill_ratio - target_ratio) ** 2
    return np.where(remaining < 0, -np.inf, -np.exp(penalty))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    filled = bins - remaining
    target = 0.75 * bins
    score = -((filled - target) ** 2) / (0.15 * bins + 1e-8)
    return np.where(remaining < 0, -np.inf, score)

