def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target_remaining = 0.4 * bins
    score = -((remaining - target_remaining) ** 2) / (0.2 * bins + 1e-8)
    return np.where(remaining < 0, -np.inf, score)
